  "header.subtitle": { en: "Six econometric case studies — from production functions to causal inference — each with its own dataset and interactive visualization.", es: "Seis estudios de caso econométricos — desde funciones de producción hasta inferencia causal — cada uno con su propio conjunto de datos y visualización interactiva.", ja: "6つの計量経済学のケーススタディ — 生産関数から因果推論まで — それぞれが独自のデータセットとインタラクティブな可視化を備えています。" },
  "meta.title": { en: "Chapter 13 — Case Studies for Multiple Regression · metricsAI", es: "Capítulo 13 — Estudios de caso para regresión múltiple · metricsAI", ja: "第13章 — 重回帰のケーススタディ · metricsAI" },
  "nav.cobbdouglas": { en: "Cobb-Douglas", es: "Cobb-Douglas", ja: "Cobb-Douglas" },
  "nav.did": { en: "Diff-in-Diff", es: "Dif-en-Dif", ja: "DiD" },
