  "nav.rd": { en: "Regression Disc.", es: "Regresión disc.", ja: "回帰不連続" },
  "widget.cd.callout": { en: "<strong>Capital elasticity α = {alpha}</strong>, <strong>labor elasticity β = {beta}</strong>. Sum = {sum} ≈ 1. The F-test for constant returns to scale gives p = {crs_p} — we cannot reject CRS at any conventional level.", es: "<strong>Elasticidad del capital α = {alpha}</strong>, <strong>elasticidad del trabajo β = {beta}</strong>. Suma = {sum} ≈ 1. La prueba F para rendimientos constantes a escala da p = {crs_p} — no podemos rechazar RCE en ningún nivel convencional.", ja: "<strong>資本の弾力性 α = {alpha}</strong>、<strong>労働の弾力性 β = {beta}</strong>。合計 = {sum} ≈ 1。規模に関して収穫一定のF検定はp = {crs_p}を与えます — 通常のどの有意水準でもCRSを棄却できません。" },
  "widget.cd.chart.actual": { en: "Actual output", es: "Producción real", ja: "実績生産量" },
  "widget.cd.chart.predicted": { en: "Predicted (Cobb-Douglas)", es: "Predicha (Cobb-Douglas)", ja: "予測値 (Cobb-Douglas)" },
